                PointUtil.convertPathAbbreviatedDatatoPoint("M 10 20 L 30 40 S 50 60");

        assertEquals(3, points.size());

        assertEquals("M", points.get(0).type);
        assertEquals(10f, points.get(0).x1, EPS);
        assertEquals(20f, points.get(0).y1, EPS);
        assertEquals(0f, points.get(0).x2, EPS);
        assertEquals(0f, points.get(0).y3, EPS);

        assertEquals("L", points.get(1).type);
        assertEquals(30f, points.get(1).x1, EPS);
        assertEquals(40f, points.get(1).y1, EPS);
        assertEquals(0f, points.get(1).x2, EPS);

        assertEquals("S", points.get(2).type);
        assertEquals(50f, points.get(2).x1, EPS);
        assertEquals(60f, points.get(2).y1, EPS);
        assertEquals(0f, points.get(2).y3, EPS);
    }

