        ST_Array compositeCtm = new ST_Array(1, 0, 0, 1, 1, 2);

        List<PathPoint> points = PointUtil.calPdfPathPoint(
                100, 200, null, input, false, null, compositeBoundary, compositeCtm, false);

        // (10 + 1 + 5, 20 + 2 + 7) = (16, 29)
        assertEquals(45.3543, points.get(0).x1, EPS);
        assertEquals(82.2047, points.get(0).y1, EPS);
    }

    @Test
    public void calPdfPathPoint_treatsDetectedLegacyCoordinatesAs300Dpi() {
        List<PathPoint> input =
                Collections.singletonList(new PathPoint("M", 1000, 1000, 0, 0, 0, 0));
        ST_Box boundary = new ST_Box(0, 0, 210, 297);
        ST_Array ctm = new ST_Array(1, 0, 0, 1, 10000, 10000);

        List<PathPoint> points = PointUtil.calPdfPathPoint(
                210, 297, boundary, input, true, ctm, null, null, false);

        // 1000 * (25.4 / 300) mm converted to points is 1000 * 72 / 300 = 240.
        assertEquals(240.0, points.get(0).x1, EPS);
        assertEquals(240.0, points.get(0).y1, EPS);
    }

