    @Test
    public void calPdfTextCoordinate_decodesXmlEntitiesAndDropsLineBreaks() {
        TextCode entities = new TextCode();
        entities.setContent("&lt;x&gt;");
        entities.setCoordinate(0d, 0d);

        TextCode lineBreak = new TextCode();
        lineBreak.setContent("a\nb");
        lineBreak.setCoordinate(0d, 0d);

        TextCode named = new TextCode();
        named.setContent("&nbsp;&copy;&apos;&quot;");
        named.setCoordinate(0d, 0d);

        List<TextCode> textCodes = new ArrayList<>();
        textCodes.add(entities);
        textCodes.add(lineBreak);
        textCodes.add(named);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, textCodes, false, null, false, 1);

        assertEquals(8, points.size());
        assertEquals("<", points.get(0).getText());
        assertEquals("x", points.get(1).getText());
        assertEquals(">", points.get(2).getText());
        assertEquals("a", points.get(3).getText());
        assertEquals("b", points.get(4).getText());
        assertEquals(" ", points.get(5).getText());
        assertEquals("'", points.get(6).getText());
        assertEquals("\"", points.get(7).getText());
    }

    @Test
    public void calPdfTextCoordinate_appliesCtmTranslationOnceAndTreatsDeltasAsVectors() {
        TextCode textCode = new TextCode();
        textCode.setContent("AB");
        textCode.setCoordinate(10d, 20d);
        textCode.setDeltaX(1d);
        textCode.setDeltaY(0d);
        ST_Array ctm = new ST_Array(1, 0, 0, 1, 5, 7);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode), true, ctm, false, 1);

        assertEquals(2, points.size());
        assertEquals(42.5197, points.get(0).getX(), EPS);
        assertEquals(76.5354, points.get(0).getY(), EPS);
        // The translation must not be counted again for the delta vector.
        assertEquals(45.3543, points.get(1).getX(), EPS);
        assertEquals(76.5354, points.get(1).getY(), EPS);
    }

    @Test
    public void calPdfTextCoordinate_appliesBoundaryAndScale() {
        TextCode textCode = new TextCode();
        textCode.setContent("A");
        textCode.setCoordinate(10d, 20d);
